</head>
<body>
<textarea id="lolcrraw" style="display:none;position:absolute;left:-9999px">$1</textarea>
<div id="lolcrwin">
  <div id="lolcrhead">
    <div id="lolcrico">
      <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
        <rect x="3" y="1.5" width="5" height="4.5" rx="1" fill="#C89B3C" opacity=".9"/>
        <rect x="1.5" y="3" width="8" height="2" rx="1" fill="#C89B3C" opacity=".6"/>
        <line x1="7" y1="6" x2="13.5" y2="13.5" stroke="#C89B3C" stroke-width="2.2" stroke-linecap="round"/>
      </svg>
    </div>
    <div id="lolcrhdtxt">
      <div id="lolcrtitle">CRAFTING REQUEST</div>
      <div id="lolcrintent">—</div>
    </div>
    <div id="lolcrbadge">⚒ FORGE</div>
  </div>
  <div id="lolcrbody"></div>
  <div id="lolcrfoot">RUNETERRA FORGE</div>
</div>
<script>
(function(){
  function g(id){return document.getElementById(id);}
  function esc(v){if(v==null)return '';return String(v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}

  var rawEl=g('lolcrraw'); if(!rawEl)return;
  var raw=(rawEl.value||'').replace(/<\/?LOL_CRAFT>/gi,'').trim();
  var d={}; try{d=JSON.parse(raw);}catch(e){}

  var TH=(d.lang==='th');
  var ingredients=Array.isArray(d.ingredients)?d.ingredients:[];
  var intent=d.intent||'';

  var win=g('lolcrwin'); if(!win)return;

  // Header intent
  var it=g('lolcrintent');
  if(it)it.textContent=intent||'—';

  // Count badge
  var badge=g('lolcrbadge');
  if(badge)badge.textContent='⚒ '+ingredients.length+(TH?' รายการ':' item'+(ingredients.length!==1?'s':''));

  var ft=g('lolcrfoot');
  if(ft)ft.textContent=TH?'เตาหลอมแห่งรูนเทอร์รา':'RUNETERRA FORGE';

  // Parse ingredient string: "Iron Ore ×2" → name="Iron Ore", qty="×2"
  function parseIngr(s){
    var m=String(s).match(/^(.*?)\s*(×\d+|\(\d+\)|\d+$)?\s*$/);
    if(m)return {name:(m[1]||s).trim(),qty:m[2]||''};
    return {name:s,qty:''};
  }

  function ingredIcon(name){
    var n=(name||'').toLowerCase();
    if(/ore|metal|iron|steel|copper|gold|silver|alloy/.test(n))return '◼';
    if(/wood|timber|plank|branch|oak|pine/.test(n))return '◻';
    if(/leather|hide|skin|fur|pelt/.test(n))return '◇';
    if(/herb|flower|leaf|root|plant|seed|petal/.test(n))return '◈';
    if(/crystal|gem|stone|rune|shard|quartz/.test(n))return '◆';
    if(/bone|fang|claw|tooth|scale/.test(n))return '▲';
    if(/cloth|silk|thread|fiber|linen/.test(n))return '◁';
    if(/venom|poison|acid|toxin|gland/.test(n))return '⬡';
    if(/scroll|paper|ink|tome|book/.test(n))return '▷';
    return '◉';
  }

  // Build body
  var body=g('lolcrbody'); if(!body)return;

  if(!ingredients.length){
    body.innerHTML='<div class="lolcr-sec">'+(TH?'ส่วนผสม':'INGREDIENTS')+'</div><div style="font-size:10px;color:var(--tx3);font-style:italic;padding:4px 0">'+(TH?'ไม่มีส่วนผสม':'No ingredients specified')+'</div>';
    return;
  }

  var chips=ingredients.map(function(s){
    var p=parseIngr(s);
    var ico=ingredIcon(p.name);
    return '<div class="lolcr-chip">'+
      '<span class="lolcr-chip-ico">'+ico+'</span>'+
      '<span class="lolcr-chip-name">'+esc(p.name)+'</span>'+
      (p.qty?'<span class="lolcr-chip-qty">'+esc(p.qty)+'</span>':'')+
    '</div>';
  }).join('');

  body.innerHTML=
    '<div class="lolcr-sec">'+(TH?'ส่วนผสม':'INGREDIENTS')+'</div>'+
    '<div class="lolcr-chips">'+chips+'</div>';
})();
</script>
</body>
</html>

